ebbol kuldj vissza egy css sablont: <!DOCTYPE html>
<html lang="hu">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover, interactive-widget=resizes-content">
    <title>JADED - Deep Discovery AI Platform</title>

    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
    <meta name="apple-mobile-web-app-title" content="JADED">
    <meta name="mobile-web-app-capable" content="yes">
    <meta name="theme-color" content="#000000">
    <meta name="apple-touch-fullscreen" content="yes">
    <meta name="format-detection" content="telephone=no">

    <link rel="apple-touch-icon" sizes="180x180" href="image/svg+xml,%3Csvg xmlns='' viewBox='0 0 100 100'%3E%3Crect width='100' height='100' fill='%23000' rx='22'/%3E%3Cpath d='M 30 28 C 30 50 50 72 70 72' stroke='white' stroke-width='8' fill='none' stroke-linecap='round'/%3E%3Ccircle cx='30' cy='72' r='6' fill='white'/%3E%3C/svg%3E">

    <link rel="manifest" href="application/manifest+json,%7B%22name%22%3A%22JADED%20-%20Deep%20Discovery%20AI%20Platform%22%2C%22short_name%22%3A%22JADED%22%2C%22description%22%3A%22Fejlett%20AI%20platform%20tudom%C3%A1nyos%20szolg%C3%A1ltat%C3%A1sokkal%22%2C%22start_url%22%3A%22%2F%22%2C%22display%22%3A%22standalone%22%2C%22orientation%22%3A%22portrait-primary%22%2C%22theme_color%22%3A%22%23000000%22%2C%22background_color%22%3A%22%23000000%22%2C%22scope%22%3A%22%2F%22%2C%22lang%22%3A%22hu%22%2C%22categories%22%3A%5B%22science%22%2C%22utilities%22%5D%7D">

    <style>
        @import url('');

        :root {
            --primary: #0A61F7; 
            --secondary: #39FF14; 
            --accent: #0A61F7;
            --border-glow: rgba(10, 97, 247, 0.5); 
            --primary-rgb: 10, 97, 247; 
            --secondary-rgb: 57, 255, 20;
            --bg: #000000; 
            --surface: rgba(10, 10, 10, 0.7); 
            --glass: rgba(255, 255, 255, 0.02);
            --glass-strong: rgba(255, 255, 255, 0.05); 
            --border: rgba(255, 255, 255, 0.08);
            --text: #f0f0f0; 
            --text-muted: #94a3b8; 
            --radius-lg: 24px; 
            --radius-md: 16px; 
            --radius-sm: 12px;
            --shadow: 0 12px 48px rgba(0, 0, 0, 0.6);
            --transition-curve: cubic-bezier(0.25, 0.8, 0.25, 1); 
            --transition-color-slow: 15s ease-in-out;
        }
        * { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
        html { height: 100%; height: -webkit-fill-available; scroll-behavior: smooth; }
        body {
            font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text);
            min-height: 100vh; min-height: -webkit-fill-available; overflow: hidden;
            -webkit-font-smoothing: antialiased; font-size: 15px;
        }
        .aurora-background { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; pointer-events: none; z-index: -1; overflow: hidden; will-change: transform; }
        .aurora { position: absolute; border-radius: 50%; mix-blend-mode: screen; filter: blur(120px); opacity: 0; transition: background-color var(--transition-color-slow), opacity 8s ease-in-out; animation: pulse 30s ease-in-out infinite alternate; will-change: transform, opacity; }
        .aurora.visible { opacity: 0.3; }
        .aurora.one { width: 80vmax; height: 80vmax; animation-name: move-one, pulse; animation-duration: 1200s, 35s; animation-timing-function: linear, ease-in-out; animation-iteration-count: infinite, infinite; animation-direction: alternate, alternate; }
        .aurora.two { width: 70vmax; height: 70vmax; animation-name: move-two, pulse; animation-duration: 1050s, 40s; animation-timing-function: linear, ease-in-out; animation-iteration-count: infinite, infinite; animation-direction: alternate, alternate; }
        @keyframes move-one { from { transform: translate(-20vw, -20vh) scale(1); } to { transform: translate(50vw, 80vh) scale(1.2); } }
        @keyframes move-two { from { transform: translate(80vw, 30vh) scale(1); } to { transform: translate(-10vw, 60vh) scale(1.3); } }
        @keyframes pulse { from { opacity: 0.2; } to { opacity: 0.4; } }
        .container { display: flex; min-height: 100vh; min-height: -webkit-fill-available; position: relative; }

        .welcome-title, .modal-title, .header-title { background: linear-gradient(135deg, var(--primary), var(--secondary)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
        .header-title { text-shadow: 0 0 15px var(--border-glow); font-size: 1.2rem; }
        .category-title i, .accent { color: var(--accent); }
        .service-item:hover { border-left-color: var(--primary); }

        .sidebar { width: 260px; background: var(--surface); backdrop-filter: blur(60px) saturate(180%); border-right: 1px solid var(--border); overflow-x: hidden; position: fixed; height: 100vh; height: -webkit-fill-available; z-index: 1000; transform: translateX(-100%); transition: transform 0.4s var(--transition-curve); display: flex; flex-direction: column; will-change: transform; }
        .sidebar.open { transform: translateX(0); }
        .sidebar-overlay { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; background: rgba(0, 0, 0, 0.5); backdrop-filter: blur(10px); z-index: 999; opacity: 0; visibility: hidden; transition: opacity 0.4s ease, visibility 0.4s ease; will-change: opacity; }
        .sidebar-overlay.active { opacity: 1; visibility: visible; }
        .sidebar-header { padding: 12px; border-bottom: 1px solid var(--border); }
        .logo { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
        .logo-icon { width: 28px; height: 28px; transition: transform 0.3s var(--transition-curve); }
        .logo:hover .logo-icon { transform: scale(1.15) rotate(10deg); }
        .logo-text h1 { font-size: 1.1rem; font-weight: 700; line-height: 1.1; background: linear-gradient(135deg, var(--primary), var(--secondary)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
        .logo-text p { font-size: 0.7rem; color: var(--text-muted); margin-top: 1px; font-weight: 500; }
        .new-chat-btn { width: 100%; background: var(--glass-strong); border: 1px solid var(--border); color: var(--text); border-radius: var(--radius-md); padding: 8px 10px; font-weight: 600; font-size: 0.8rem; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 6px; transition: all 0.2s var(--transition-curve); }
        .new-chat-btn:hover { transform: translateY(-2px); border-color: var(--border-glow); box-shadow: 0 4px 15px -5px rgba(0,0,0,0.4), 0 0 10px -5px var(--border-glow); }
        .sidebar-content { padding: 12px; flex-grow: 1; overflow-y: auto; }
        .sidebar-footer { padding: 12px; border-top: 1px solid var(--border); }
        .made-by { font-size: 0.7rem; color: var(--text-muted); text-align: center; }
        .service-category { margin-bottom: 12px; }
        .category-header { background: var(--glass); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 8px 10px; cursor: pointer; display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px; transition: all 0.2s var(--transition-curve); min-height: 40px; }
        .category-header .fa-chevron-down { transition: transform 0.3s var(--transition-curve); }
        .category-header:hover { background: var(--glass-strong); border-color: var(--border-glow); transform: translateY(-1px); }
        .category-title { display: flex; align-items: center; gap: 8px; font-weight: 600; font-size: 0.8rem; }
        .category-services { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.4s ease-out; }
        .category-services > div { overflow: hidden; }
        .category-services.open { grid-template-rows: 1fr; }
        .service-item { background: transparent; border: 1px solid transparent; border-radius: var(--radius-sm); padding: 8px 10px; margin-bottom: 4px; cursor: pointer; transition: all 0.2s var(--transition-curve); display: flex; align-items: center; gap: 8px; margin-left: 6px; border-left: 2px solid var(--border); min-height: 44px; }
        .service-item:hover { background: var(--glass-strong); border-color: transparent transparent transparent var(--primary); transform: translateX(4px); color: #fff; }
        .service-icon { width: 28px; height: 28px; background: var(--glass-strong); border: 1px solid var(--border); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; font-size: 0.9rem; flex-shrink: 0; color: var(--accent); transition: all 0.3s var(--transition-curve); box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3); }
        .service-item:hover .service-icon { transform: scale(1.1) rotate(5deg); box-shadow: 0 4px 10px var(--border-glow); border-color: var(--border-glow); }
        .service-info h4 { font-size: 0.8rem; font-weight: 600; margin-bottom: 2px; }
        .service-info p { font-size: 0.7rem; color: var(--text-muted); }

        .main-content { flex: 1; margin-left: 0; display: flex; flex-direction: column; transition: margin-left 0.4s var(--transition-curve); min-height: 100vh; min-height: -webkit-fill-available; max-height: 100vh; max-height: -webkit-fill-available; overflow: hidden; }
        .header { padding: 8px 12px; height: 48px; background: var(--surface); backdrop-filter: blur(60px) saturate(180%); border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between; position: sticky; top: 0; z-index: 100; }
        .menu-toggle { background: var(--glass-strong); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 6px; color: var(--text); cursor: pointer; transition: all 0.2s var(--transition-curve); font-size: 0.9rem; width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; }
        .menu-toggle:hover { background: var(--glass-strong); border-color: var(--border-glow); transform: scale(1.05); }
        .chat-area { flex: 1; display: flex; flex-direction: column; overflow-y: auto; }
        .messages-container { padding: 12px; overflow-y: auto; flex: 1; }
        .welcome-screen { text-align: center; max-width: 500px; margin: 0 auto; padding: 30px 20px; display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; animation: fadeIn 1s var(--transition-curve); }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        .welcome-title { font-size: 2.2rem; margin-bottom: 0.5rem; font-weight: 800; }
        .welcome-subtitle { font-size: 0.9rem; line-height: 1.5; margin-bottom: 1.2rem; color: var(--text-muted); }
        .start-btn { padding: 10px 20px; font-size: 0.9rem; min-height: 42px; background: var(--glass-strong); border: 1px solid var(--border); border-radius: var(--radius-md); color: var(--text); font-weight: 600; cursor: pointer; transition: all 0.2s var(--transition-curve); display: inline-flex; align-items: center; gap: 8px; }
        .start-btn:hover { border-color: var(--border-glow); transform: translateY(-2px) scale(1.03); }

        /* Service Interface Styles */
        .service-interface { padding: 20px; max-width: 1200px; margin: 0 auto; animation: fadeIn 0.5s ease; }
        .interface-header { text-align: center; margin-bottom: 25px; }
        .interface-header h2 { display: flex; align-items: center; justify-content: center; gap: 10px; margin-bottom: 8px; font-size: 1.4rem; }
        .interface-header p { color: var(--text-muted); font-size: 0.95rem; line-height: 1.4; }
        .interface-content { background: var(--glass); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 24px; }
        .input-section { margin-bottom: 25px; }
        .input-section h3 { margin-bottom: 15px; color: var(--text); font-size: 1.1rem; }
        .input-section textarea, .input-section input, .input-section select { width: 100%; background: var(--glass-strong); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 12px; color: var(--text); font-size: 0.9rem; font-family: inherit; transition: border-color 0.2s ease; }
        .input-section textarea:focus, .input-section input:focus, .input-section select:focus { outline: none; border-color: var(--primary); }
        .input-section textarea { resize: vertical; min-height: 120px; font-family: 'SF Mono', monospace; }
        .options-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-top: 20px; }
        .option-group { display: flex; flex-direction: column; gap: 6px; }
        .option-group label { font-size: 0.8rem; font-weight: 600; color: var(--text); }
        .action-buttons { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 30px; }
        .primary-btn, .secondary-btn { padding: 10px 16px; border-radius: var(--radius-md); border: 1px solid var(--border); font-weight: 600; font-size: 0.85rem; cursor: pointer; transition: all 0.2s var(--transition-curve); display: inline-flex; align-items: center; gap: 8px; min-height: 42px; }
        .primary-btn { background: linear-gradient(135deg, var(--primary), var(--secondary)); color: white; border-color: var(--primary); }
        .primary-btn:hover { transform: translateY(-2px); box-shadow: 0 4px 15px rgba(var(--primary-rgb), 0.4); }
        .secondary-btn { background: var(--glass-strong); color: var(--text); }
        .secondary-btn:hover { background: var(--glass-strong); border-color: var(--primary); transform: translateY(-1px); }
        .result-section { margin-top: 30px; padding-top: 20px; border-top: 1px solid var(--border); }
        .result-section h3 { font-size: 1rem; font-weight: 600; margin-bottom: 16px; color: var(--text); }
        .result-section pre { background: rgba(0,0,0,0.4); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 12px; margin: 12px 0; font-size: 0.85rem; overflow-x: auto; }
        .result-section code { font-family: 'SF Mono', 'Fira Code', monospace; }
        .status-indicator { padding: 15px; border-radius: var(--radius-md); margin: 10px 0; display: flex; align-items: center; gap: 10px; font-weight: 600; }
        .status-running { background: rgba(var(--primary-rgb), 0.1); color: var(--primary); border: 1px solid rgba(var(--primary-rgb), 0.3); }
        .status-error { background: rgba(239, 68, 68, 0.1); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3); }

        .tab-selector { display: flex; gap: 5px; margin-bottom: 20px; background: var(--glass); border-radius: var(--radius-md); padding: 5px; }
        .tab-btn { background: transparent; border: none; color: var(--text-muted); padding: 8px 16px; border-radius: var(--radius-sm); cursor: pointer; transition: all 0.2s var(--transition-curve); font-weight: 500; font-size: 0.85rem; }
        .tab-btn.active, .tab-btn:hover { background: var(--glass-strong); color: var(--text); }
        .tab-content { display: none; }
        .tab-content.active { display: block; animation: fadeIn 0.4s ease; }
        .glass-card { background: var(--glass); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 15px; margin-bottom: 15px; }
        .sequence-stats { display: flex; justify-content: space-between; align-items: center; font-size: 0.8rem; color: var(--text-muted); margin-top: 10px; }

        @media (max-width: 768px) {
            .sidebar { width: 100vw; }
            .main-content { margin-left: 0; }
            .welcome-title { font-size: 1.8rem; }
            .service-interface { padding: 16px; }
            .interface-content { padding: 16px; }
        }
    </style>
</head>

<body>
    <div class="aurora-background">
        <div class="aurora one"></div>
        <div class="aurora two"></div>
    </div>
    <div class="sidebar-overlay" id="sidebarOverlay"></div>

    <div class="container">
        <aside class="sidebar" id="sidebar" role="navigation">
            <header class="sidebar-header">
                <div class="logo">
                    <div class="logo-icon" id="logo-icon-container"></div>
                    <div class="logo-text">
                        <h1>JADED</h1>
                        <p>Deep Discovery AI Platform</p>
                    </div>
                </div>
                <button class="new-chat-btn" onclick="newSession()">
                    <i class="fas fa-home"></i>
                    Főoldal
                </button>
            </header>
            <div class="sidebar-content" id="sidebarContent"></div>
            <footer class="sidebar-footer">
                <p class="made-by">JADED v2.1 by Sándor Kollár</p>
            </footer>
        </aside>

        <main class="main-content" id="mainContent">
            <header class="header">
                <button class="menu-toggle" onclick="toggleSidebar()" aria-label="Menü megnyitása/bezárása">
                    <i class="fas fa-bars"></i>
                </button>
                <h1 class="header-title" id="headerTitle">JADED</h1>
            </header>

            <div class="chat-area" id="messagesContainer">
                <header class="welcome-screen" id="welcomeScreen">
                    <h1 class="welcome-title">Üdv a JADED platformon!</h1>
                    <p class="welcome-subtitle">
                        A bal oldali menüből válassz egy szolgáltatást a kezdéshez. 
                        Az **AlphaFold Viewer** egy interaktív felület a protein szerkezet előrejelzéséhez.
                    </p>
                    <button class="start-btn" onclick="toggleSidebar()">
                        <i class="fas fa-bars"></i>
                        Szolgáltatások
                    </button>
                </header>
            </div>
        </main>
    </div>

    <link rel="stylesheet" href="" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="" integrity="sha512-D9gUyxqja7hBtkWpPWGt9wfb5F/sc7FpdaSMfPMrJc3CkzXPgAenPhJ4HCWJeQ30/eIs40+o8SjF9WZpBFjJ2w==" crossorigin="anonymous" referrerpolicy="no-referrer"></script>

    <script>
        // --- DOM Elements ---
        const getEl = (id) => document.getElementById(id);
        const sidebar = getEl('sidebar');
        const sidebarOverlay = getEl('sidebarOverlay');
        const sidebarContent = getEl('sidebarContent');
        const messagesContainer = getEl('messagesContainer');
        const headerTitle = getEl('headerTitle');
        let welcomeScreen = getEl('welcomeScreen');

        // --- Theme Manager (Static Blue-Green) ---
        class DynamicThemeManager {
            constructor() {
                const root = document.documentElement;
                const auroraBlobs = document.querySelectorAll('.aurora-background .aurora');
                const colorPair = { primary: '#0A61F7', secondary: '#39FF14' };

                const primaryRGB = this.hexToRgb(colorPair.primary);
                root.style.setProperty('--primary', colorPair.primary);
                root.style.setProperty('--secondary', colorPair.secondary);
                root.style.setProperty('--accent', colorPair.primary);
                root.style.setProperty('--border-glow', `rgba(${primaryRGB}, 0.5)`);
                root.style.setProperty('--primary-rgb', primaryRGB);
                auroraBlobs.forEach((blob, i) => { blob.style.backgroundColor = i % 2 === 0 ? colorPair.primary : colorPair.secondary; });

                setTimeout(() => auroraBlobs.forEach(b => b.classList.add('visible')), 500);
            }
            hexToRgb = (hex) => {
                let r=0,g=0,b=0;
                if(hex.length==7){r=parseInt(hex.substring(1,3),16);g=parseInt(hex.substring(3,5),16);b=parseInt(hex.substring(5,7),16);}
                return `${r},${g},${b}`;
            };
        }

        // --- Core UI Functions ---
        function createSVGLogo() {
            getEl('logo-icon-container').innerHTML = `<svg viewBox="0 0 100 100" xmlns="" style="width:100%;height:100%;"><path d="M 30 28 C 30 50 50 72 70 72" stroke="rgba(255,255,255,0.8)" stroke-width="8" fill="none" stroke-linecap="round"/><circle cx="30" cy="72" r="6" fill="rgba(255,255,255,0.8)"/></svg>`;
        }
        function toggleSidebar() { sidebar.classList.toggle('open'); sidebarOverlay.classList.toggle('active'); }
        function closeSidebar() { sidebar.classList.remove('open'); sidebarOverlay.classList.remove('active'); }
        function hideWelcome() { if (welcomeScreen) { welcomeScreen.style.display = 'none'; welcomeScreen = null; } }
        function newSession() {
            messagesContainer.innerHTML = '';
            const newWelcomeScreen = document.createElement('header');
            newWelcomeScreen.className = 'welcome-screen';
            newWelcomeScreen.id = 'welcomeScreen';
            newWelcomeScreen.innerHTML = `<h1 class="welcome-title">Üdv a JADED platformon!</h1><p class="welcome-subtitle">A bal oldali menüből válassz egy szolgáltatást a kezdéshez. Az **AlphaFold Viewer** egy interaktív felület a protein szerkezet előrejelzéséhez.</p><button class="start-btn" onclick="toggleSidebar()"><i class="fas fa-bars"></i> Szolgáltatások</button>`;
            messagesContainer.appendChild(newWelcomeScreen);
            welcomeScreen = getEl('welcomeScreen');
            headerTitle.textContent = 'JADED';
            closeSidebar();
        }

        // --- Service Loading ---
        function loadServices() {
            const servicesData = {
                "Tudományos Modellezés": {
                    icon: "fa-dna",
                    services: {
                        "AlphaFold Viewer": "Protein szerkezet predikció",
                        "AlphaGenome Viewer": "Genomikai elemzés és vizualizáció",
                        "3D Viewer": "3D modellek és adathalmazok megjelenítése"
                    }
                },
                "Kutatási Eszközök": {
                    icon: "fa-microscope",
                    services: {
                        "Deep Search": "Mélyreható tudományos keresés",
                        "Services Navigation": "Szolgáltatások közötti navigáció"
                    }
                }
            };

            sidebarContent.innerHTML = '';
            for (const categoryName in servicesData) {
                const category = servicesData[categoryName];
                let servicesHTML = Object.entries(category.services).map(([serviceName, description]) => 
                    `<div class="service-item" onclick="selectService('${escapeHtml(serviceName).replace(/'/g, "\\'")}', '${escapeHtml(description).replace(/'/g, "\\'")}')">
                        <div class="service-icon"><i class="fas fa-flask"></i></div>
                        <div class="service-info">
                            <h4>${escapeHtml(serviceName)}</h4>
                            <p>${escapeHtml(description)}</p>
                        </div>
                    </div>`
                ).join('');

                const categoryDiv = document.createElement('div');
                categoryDiv.className = 'service-category';
                categoryDiv.innerHTML = `
                    <div class="category-header" onclick="toggleCategory(this)">
                        <div class="category-title"><i class="fas ${category.icon}"></i><span>${categoryName}</span></div>
                        <i class="fas fa-chevron-down"></i>
                    </div>
                    <div class="category-services"><div>${servicesHTML}</div></div>`;
                sidebarContent.appendChild(categoryDiv);
            }
        }
        function toggleCategory(header) {
            const categoryServices = header.nextElementSibling;
            const chevron = header.querySelector('.fa-chevron-down');
            categoryServices.classList.toggle('open');
            chevron.style.transform = categoryServices.classList.contains('open') ? 'rotate(180deg)' : 'rotate(0deg)';
        }
        function selectService(serviceName, description) { 
            hideWelcome();
            headerTitle.textContent = serviceName;
            showServiceInterface(serviceName, description); 
            closeSidebar(); 
        }

        // --- Service Interface Rendering ---
        function showServiceInterface(serviceName, description) {
            if (serviceName.includes('AlphaFold')) {
                showAlphaFoldInterface();
            } else {
                showStaticViewerInterface(serviceName, description);
            }
        }

        function showAlphaFoldInterface() {
            const interfaceHTML = `
                <div class="service-interface">
                    <div class="interface-header">
                        <h2><i class="fas fa-dna accent"></i> AlphaFold Protein Szerkezet Predikció</h2>
                        <p>Adjon meg egy protein szekvenciát a 3D szerkezetének előrejelzéséhez a backend mock szolgáltatásával.</p>
                    </div>
                    <div class="interface-content">
                        <div class="tab-selector">
                            <button class="tab-btn active">Szekvencia Bevitel</button>
                        </div>
                        <div class="tab-content active">
                            <div class="input-section glass-card">
                                <h3>Protein Szekvencia</h3>
                                <textarea id="proteinSequence" placeholder="Írja be a protein szekvenciát (pl. 'GSWTEHKPDE')..." rows="8"></textarea>
                                <div class="sequence-stats">
                                    <span id="sequence-length">Hossz: 0</span>
                                </div>
                            </div>
                        </div>
                        <div class="action-buttons">
                            <button class="primary-btn" onclick="runAlphaFoldPrediction()">
                                <i class="fas fa-rocket"></i> Predikció Indítása
                            </button>
                        </div>
                        </div>
                </div>`;
            messagesContainer.innerHTML = interfaceHTML;
            getEl('proteinSequence').addEventListener('input', updateSequenceStats);
        }

        function showStaticViewerInterface(serviceName, description) {
            const icons = {
                "AlphaGenome Viewer": "fa-microscope",
                "3D Viewer": "fa-cube",
                "Deep Search": "fa-search",
                "Services Navigation": "fa-compass"
            };
            const iconClass = icons[serviceName] || 'fa-window-maximize';
            const interfaceHTML = `
                <div class="service-interface">
                    <div class="interface-header">
                         <h2><i class="fas ${iconClass} accent"></i> ${serviceName}</h2>
                         <p>${description}</p>
                    </div>
                    <div class="interface-content">
                        <p>Ez a felület a(z) <strong>${serviceName}</strong> szolgáltatás megjelenítésére szolgál. A jelenlegi backend konfigurációban ez egy statikus nézet.</p>
                    </div>
                </div>`;
            messagesContainer.innerHTML = interfaceHTML;
        }

        // --- Backend Communication & Logic ---
        function updateSequenceStats() { 
            const seq = getEl('proteinSequence').value;
            getEl('sequence-length').textContent = `Hossz: ${seq.replace(/[^A-Za-z]/g, '').length}`;
        }

        async function runAlphaFoldPrediction() {
            const sequence = getEl('proteinSequence').value.trim();
            if (!sequence) {
                displayError("A szekvencia nem lehet üres.");
                return;
            }

            showProgress('Predikció küldése a szervernek...');

            try {
                const response = await fetch('/predict', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ sequence: sequence })
                });

                if (!response.ok) {
                    const errorData = await response.json();
                    throw new Error(errorData.message || `HTTP hiba: ${response.status}`);
                }

                const result = await response.json();
                displayResults(result, 'AlphaFold Predikciós Eredmény');

            } catch (error) {
                console.error("Hiba a predikció során:", error);
                displayError(`Hiba történt: ${error.message}`);
            }
        }

        // --- Result Display ---
        function showProgress(message) {
            const container = document.querySelector('.service-interface .interface-content');
            if (!container) return;

            let resultSection = container.querySelector('.result-section');
            if (!resultSection) {
                resultSection = document.createElement('div');
                resultSection.className = 'result-section';
                container.appendChild(resultSection);
            }

            resultSection.innerHTML = `<div class="status-indicator status-running"><i class="fas fa-spinner fa-spin"></i><span>${message}</span></div>`;
        }

        function displayResults(data, title) {
            const container = document.querySelector('.service-interface .interface-content');
            if (!container) return;

            let resultSection = container.querySelector('.result-section');
            if (!resultSection) {
                resultSection = document.createElement('div');
                resultSection.className = 'result-section';
                container.appendChild(resultSection);
            }

            const resultHTML = `
                <h3><i class="fas fa-check-circle" style="color: #39FF14;"></i> ${title}</h3>
                <p>A szerver a következő (mock) adatokat küldte vissza:</p>
                <pre><code>${escapeHtml(JSON.stringify(data, null, 2))}</code></pre>
                <div class="action-buttons">
                    <button class="secondary-btn" onclick="showAlphaFoldInterface()">
                        <i class="fas fa-redo"></i> Új Predikció
                    </button>
                </div>`;
            resultSection.innerHTML = resultHTML;
            if (typeof hljs !== 'undefined') { hljs.highlightAll(); }
        }

        function displayError(message) {
            const container = document.querySelector('.service-interface .interface-content');
            if (!container) return;

             let resultSection = container.querySelector('.result-section');
            if (!resultSection) {
                resultSection = document.createElement('div');
                resultSection.className = 'result-section';
                container.appendChild(resultSection);
            }

            resultSection.innerHTML = `<div class="status-indicator status-error"><i class="fas fa-exclamation-triangle"></i> ${escapeHtml(message)}</div>`;
        }

        // --- Utilities & Event Listeners ---
        function escapeHtml(text) { 
            const div = document.createElement('div'); 
            div.textContent = String(text); 
            return div.innerHTML; 
        }
        function setupEventListeners() {
            sidebarOverlay.addEventListener('click', closeSidebar);
        }

        // --- App Initialization ---
        document.addEventListener('DOMContentLoaded', () => {
            console.log('🚀 JADED Platform Initialized');
            window.themeManager = new DynamicThemeManager();
            createSVGLogo();
            setupEventListeners();
            loadServices();
        });
    </script>
</body>
